}
</code></pre>

Compose MultiplatformWrapper <pre><code>@Composable
fun MapScreen() {
    rememberAndInitializeMapKit().bindToLifecycleOwner()
    val cameraPositionState = rememberCameraPositionState { position = moscow }
    YandexMap(
        cameraPositionState = cameraPositionState,
        modifier = Modifier.fillMaxSize(),
    ) {
        Placemark(
            state = rememberPlacemarkState(Point(55.751225, 37.629540)),
            icon = imageProvider(Res.drawable.pin_red),
            onTap = { point -&gt;
                println("tapped at $point")
                true
            },
        )
    }
}
</code></pre> <pre><code>fun setupMap(map: Map, icon: ImageProvider) {
    map.mapObjects.addPlacemark().apply {
        geometry = Point(55.751225, 37.629540)
        setIcon(icon)
    }
}
</code></pre> <p><code>ImageProvider</code> is built in platform code — see Image resources.</p>

Property Type <code>name</code> <code>String?</code> <code>descriptionText</code> <code>String?</code> <code>geometry</code> <code>List&lt;Geometry&gt;</code> <code>boundingBox</code> <code>BoundingBox?</code> <code>aref</code> <code>List&lt;String&gt;</code> <code>attributionMap</code> <code>Map&lt;String, Attribution&gt;</code> <p><code>geometry</code> is a list because one object can consist of several shapes. Each <code>Geometry</code> holds exactly one of <code>point</code>, <code>polyline</code>, <code>polygon</code>, <code>multiPolygon</code>, <code>boundingBox</code> or <code>circle</code>.</p> <pre><code>val point = geoObject.geometry.firstNotNullOfOrNull { it.point }

if (point != null) {
    map.move(
        CameraPosition(point, zoom = 17f, azimuth = 0f, tilt = 0f),
        Animation(Animation.Type.SMOOTH, 300.milliseconds),
    )
}
</code></pre> <p><code>attributionMap</code> maps an attribution id to an <code>Attribution</code> with its <code>author</code>, <code>link</code> and <code>avatarImage</code> — what has to be shown next to third-party data.</p>

